WITH valid AS (SELECT id, order_id, carrier, shipped_date, delivered_date, QUARTER(shipped_date) AS shipped_date_quarter FROM shipments WHERE delivered_date >= TO_DATE('2023-04-21') AND carrier IS NOT NULL) SELECT *, NTILE(3) OVER (ORDER BY shipped_date_quarter DESC, id) AS shipped_date_quarter_bucket, LAG(shipped_date_quarter, 1, 0) OVER (PARTITION BY carrier ORDER BY shipped_date_quarter, id) AS prev_shipped_date_quarter, AVG(shipped_date_quarter) OVER (PARTITION BY order_id ORDER BY shipped_date, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS shipped_date_quarter_avg_5 FROM valid
